//! Deterministic authorization and destructive-operation classification.
#![forbid(unsafe_code)]
use std::{path::{Component,Path,PathBuf},sync::Arc}; use opencode_rk_contracts::ApprovalId; use serde::{Deserialize,Serialize};
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum FileAction{Read,Write,Delete,CreateDirectory}
#[derive(Clone,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(tag="type",rename_all="snake_case")]pub enum OperationIntent{File{action:FileAction,path:PathBuf},Process{program:String,args:Vec<String>,cwd:PathBuf},Sql{statement:String,database:String},Tool{name:String,description:String}}
#[derive(Clone,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(tag="decision",rename_all="snake_case")]pub enum Decision{Allow,Deny{reason:String},RequireHuman{approval_id:ApprovalId,reason:String}}
#[derive(Clone,Debug,Eq,PartialEq,Serialize,Deserialize)]pub struct SecurityPolicy{pub protected_mode:bool,pub destructive_command_protection:bool,pub allow_secret_reads:bool,pub project_roots:Vec<PathBuf>,pub explicitly_allowed_roots:Vec<PathBuf>,pub system_readable:bool} impl SecurityPolicy{#[must_use]pub fn lean_default(project_root:impl Into<PathBuf>)->Self{Self{protected_mode:true,destructive_command_protection:true,allow_secret_reads:false,project_roots:vec![project_root.into()],explicitly_allowed_roots:Vec::new(),system_readable:true}}}
#[derive(Clone)]pub struct PermissionBroker{generation:u64,policy:Arc<SecurityPolicy>} impl PermissionBroker{#[must_use]pub fn new(policy:SecurityPolicy)->Self{Self{generation:1,policy:Arc::new(policy)}}#[must_use]pub fn generation(&self)->u64{self.generation}#[must_use]pub fn with_policy(&self,policy:SecurityPolicy)->Self{Self{generation:self.generation.saturating_add(1),policy:Arc::new(policy)}}#[must_use]pub fn authorize(&self,intent:&OperationIntent)->Decision{match intent{OperationIntent::File{action,path}=>self.authorize_file(*action,path),OperationIntent::Process{program,args,cwd}=>self.authorize_process(program,args,cwd),OperationIntent::Sql{statement,database}=>self.authorize_sql(statement,database),OperationIntent::Tool{..}=>Decision::Allow}} fn authorize_file(&self,action:FileAction,path:&Path)->Decision{let normalized=lexical_normalize(path);if is_secret_path(&normalized)&&!self.policy.allow_secret_reads{return Decision::Deny{reason:"secret-bearing paths are not accessible to agents".to_owned()};}if is_system_path(&normalized){return match action{FileAction::Read if self.policy.system_readable=>Decision::Allow,FileAction::Read=>Decision::Deny{reason:"system-file reads are disabled by policy".to_owned()},_=>Decision::Deny{reason:"system paths are read-only to agents".to_owned()}};}if matches!(action,FileAction::Write|FileAction::Delete|FileAction::CreateDirectory)&&!self.is_within_writable_root(&normalized){return human_required("write access outside approved project roots requires explicit human approval");}if action==FileAction::Delete&&self.policy.destructive_command_protection{return human_required("file deletion requires an explicit human approval in protected mode");}Decision::Allow} fn authorize_process(&self,program:&str,args:&[String],cwd:&Path)->Decision{let executable=basename(program).to_ascii_lowercase();if is_shell_interpreter(&executable)&&args.iter().any(|arg|arg=="-c"||arg=="/c"){return human_required("opaque shell command strings require human approval; direct argv execution is preferred");}if self.policy.destructive_command_protection{if let Some(reason)=classify_destructive_argv(&executable,args,cwd){return Decision::Deny{reason};}}Decision::Allow} fn authorize_sql(&self,statement:&str,database:&str)->Decision{if !self.policy.destructive_command_protection{return Decision::Allow;}let upper=statement.to_ascii_uppercase();let words=upper.split_whitespace().take(2).collect::<Vec<_>>();match words.as_slice(){["DROP","DATABASE"|"SCHEMA"|"TABLE"]=>Decision::Deny{reason:format!("DROP is blocked in protected mode (database: {database})")},["TRUNCATE",..]=>Decision::Deny{reason:format!("TRUNCATE is blocked in protected mode (database: {database})")},["DELETE",..]if !upper.contains(" WHERE ")=>human_required("DELETE without an explicit WHERE clause requires human approval"),["ALTER","TABLE"]=>human_required("ALTER TABLE requires human approval"),_=>Decision::Allow}}fn is_within_writable_root(&self,path:&Path)->bool{self.policy.project_roots.iter().chain(&self.policy.explicitly_allowed_roots).map(|root|lexical_normalize(root)).any(|root|path.starts_with(root))}}
fn human_required(reason:&str)->Decision{Decision::RequireHuman{approval_id:ApprovalId::new(),reason:reason.to_owned()}} fn basename(program:&str)->&str{program.rsplit(['/','\\']).next().unwrap_or(program).trim_end_matches(".exe")} fn is_shell_interpreter(program:&str)->bool{matches!(program,"sh"|"bash"|"zsh"|"fish"|"dash"|"cmd"|"powershell"|"pwsh")}
#[must_use]pub fn classify_destructive_argv(program:&str,args:&[String],cwd:&Path)->Option<String>{match program{"rm"=>classify_rm(args,cwd),"rmdir"=>args.iter().any(|arg|is_system_delete_target(arg)).then(||"deleting system-level paths is never permitted for agents".to_owned()),"mkfs"|"mkfs.ext4"|"mkfs.xfs"|"format"=>Some("filesystem formatting is never executed by an agent".to_owned()),"dd"if args.iter().any(|arg|arg.starts_with("of=/dev/"))=>Some("raw-device writes are never executed by an agent".to_owned()),"find"if args.iter().any(|arg|arg=="-delete")=>Some("recursive find -delete requires a human-operated command".to_owned()),_=>None}}
fn classify_rm(args:&[String],cwd:&Path)->Option<String>{let recursive=args.iter().any(|arg|arg=="-r"||arg=="-R"||arg=="--recursive"||(arg.starts_with('-')&&arg.len()>2&&arg[1..].contains('r')));let force=args.iter().any(|arg|arg=="-f"||arg=="--force"||(arg.starts_with('-')&&arg.len()>2&&arg[1..].contains('f')));let targets:Vec<&str>=args.iter().filter(|arg|!arg.starts_with('-')).map(String::as_str).collect();if recursive&&force&&targets.iter().any(|target|is_broad_delete_target(target,cwd)){return Some("broad recursive forced deletion is blocked; present the command to the user instead".to_owned());}if targets.iter().any(|target|is_system_delete_target(target)){return Some("deleting system-level paths is never permitted for agents".to_owned());}None}fn is_broad_delete_target(target:&str,cwd:&Path)->bool{matches!(target.trim(),"*"|"./*"|"."|".."|"../"|"/")||(cwd==Path::new("/")&&matches!(target.trim(),"*"|"./*"))}fn is_system_delete_target(target:&str)->bool{let n=target.replace('\\',"/").to_ascii_lowercase();n=="/"||n.starts_with("/etc")||n.starts_with("/usr")||n.starts_with("/bin")||n.starts_with("/sbin")||n.starts_with("/boot")||n.starts_with("/system")||n.starts_with("c:/windows")||n.starts_with("c:/program files")}
fn lexical_normalize(path:&Path)->PathBuf{let mut result=PathBuf::new();for component in path.components(){match component{Component::CurDir=>{},Component::ParentDir=>{result.pop();},other=>result.push(other.as_os_str())}}result}fn is_secret_path(path:&Path)->bool{let lower=path.to_string_lossy().replace('\\',"/").to_ascii_lowercase();path.file_name().and_then(|name|name.to_str()).is_some_and(|name|name==".env"||name.starts_with(".env."))||lower.contains("/.ssh/")||lower.ends_with("/.ssh")||lower.contains("/.aws/")||lower.contains("/.config/gcloud/")||lower.contains("/credentials")}fn is_system_path(path:&Path)->bool{let lower=path.to_string_lossy().replace('\\',"/").to_ascii_lowercase();["/etc/","/usr/","/bin/","/sbin/","/boot/","/system/"].iter().any(|prefix|lower.starts_with(prefix))||matches!(lower.as_str(),"/etc"|"/usr"|"/bin"|"/sbin"|"/boot"|"/system")||lower.starts_with("c:/windows/")||lower.starts_with("c:/program files/")}
#[cfg(test)]mod tests{use super::*;fn broker()->PermissionBroker{PermissionBroker::new(SecurityPolicy::lean_default("/work/project"))}#[test]fn system_write_denied(){assert!(matches!(broker().authorize(&OperationIntent::File{action:FileAction::Write,path:PathBuf::from("/etc/hosts")}),Decision::Deny{..}));}#[test]fn env_denied(){assert!(matches!(broker().authorize(&OperationIntent::File{action:FileAction::Read,path:PathBuf::from("/work/project/.env")}),Decision::Deny{..}));}#[test]fn ordinary_project_write_allowed(){assert_eq!(broker().authorize(&OperationIntent::File{action:FileAction::Write,path:PathBuf::from("/work/project/src/lib.rs")}),Decision::Allow);}#[test]fn project_delete_human(){assert!(matches!(broker().authorize(&OperationIntent::File{action:FileAction::Delete,path:PathBuf::from("/work/project/generated.tmp")}),Decision::RequireHuman{..}));}#[test]fn rm_rf_star_blocked(){assert!(matches!(broker().authorize(&OperationIntent::Process{program:"rm".to_owned(),args:vec!["-rf".to_owned(),"*".to_owned()],cwd:PathBuf::from("/work/project")}),Decision::Deny{..}));}#[test]fn shell_c_human(){assert!(matches!(broker().authorize(&OperationIntent::Process{program:"/bin/bash".to_owned(),args:vec!["-c".to_owned(),"echo hi".to_owned()],cwd:PathBuf::from("/work/project")}),Decision::RequireHuman{..}));}#[test]fn destructive_sql_gated(){assert!(matches!(broker().authorize(&OperationIntent::Sql{statement:"DROP TABLE users".to_owned(),database:"workspace".to_owned()}),Decision::Deny{..}));}}
